#[test] fn native_popcap_research_effect_executes(){
let mut found=0;for (k,node)in r::NODES.iter().enumerate(){for ef in node.effects{if ef.field!=18{continue;}for id in 0..57{if ef.mask>>id&1==0{continue;}let mut game=crate::game::Game::new(7,0,0,1,0);game.players[0].epoch=node.epoch;game.rebuild_modifiers(0,false);let baseline=game.modifiers[0][id][18];game.researched[0][k/32]|=1u32<<(k%32);game.rebuild_modifiers(0,false);let mut expected=baseline;for f in node.effects{if f.field==18&&f.mask>>id&1==1{match f.method{0=>expected+=baseline*f.value*0.01,1=>expected+=f.value,_=>expected=f.value}}}assert_eq!(game.modifiers[0][id][18],expected);found+=1;}}}assert!(found>0);
}
